 13→// TestAgentPackages_NoForbiddenImports verifies that agent implementation packages
 14→// (claudecode, geminicli, opencode, cursor, etc.) only import from allowed packages.
 15→//
 16→// This prevents agent implementations from coupling to framework internals
 17→// (strategy, checkpoint, session, commands, hook_registry, lifecycle) which
 18→// would create brittle dependencies that break when internals change.
 19→//
 20→// Agents should depend only on:
 21→//   - The agent contract package (agent, agent/types, agent/testutil)
 22→//   - Utility packages (logging, paths, jsonutil, textutil, transcript, etc.)
 23→//   - Standard library and external dependencies
 24→func TestAgentPackages_NoForbiddenImports(t *testing.T) {
 25→	t.Parallel()
 26→
 27→	const repoPrefix = "github.com/entireio/cli/cmd/entire/cli/"
 28→
 29→	// Packages that agent implementations must NOT import.
 30→	// These are framework internals that agents should be decoupled from.
 31→	forbiddenSuffixes := []string{
 32→		"strategy",
 33→		"checkpoint",
 34→		"session",
 35→		"commands",
 36→	}
 37→
 38→	// Individual files in the cli package that agents must not depend on.
 39→	// We check for the cli package import itself since these are all in
 40→	// the top-level cli package (not sub-packages).
 41→	forbiddenCLIPackage := repoPrefix[:len(repoPrefix)-1] // "github.com/entireio/cli/cmd/entire/cli"
 42→
 43→	// Packages within the repo that agents ARE allowed to import.
 44→	allowedPrefixes := []string{
 45→		repoPrefix + "agent",      // agent contract + sub-packages
 46→		repoPrefix + "logging",    // logging utilities
 47→		repoPrefix + "paths",      // path utilities
 48→		repoPrefix + "jsonutil",   // JSON utilities
 49→		repoPrefix + "textutil",   // text utilities
 50→		repoPrefix + "transcript", // transcript utilities
 51→		repoPrefix + "trailers",   // git trailer utilities
 52→		repoPrefix + "stringutil", // string utilities
 53→		repoPrefix + "telemetry",  // telemetry
 54→		repoPrefix + "validation", // validation utilities
 55→		repoPrefix + "settings",   // settings (read-only access)
 56→	}
 57→
 58→	agentDir := findAgentDir(t)
 59→	agentPkgs := discoverAgentPackages(t, agentDir)
 60→
 61→	if len(agentPkgs) == 0 {
 62→		t.Fatal("no agent packages found — test setup is broken")
 63→	}
 64→
 65→	for _, pkgDir := range agentPkgs {
 66→		pkgName := filepath.Base(pkgDir)
 67→		t.Run(pkgName, func(t *testing.T) {
 68→			t.Parallel()
 69→			imports := extractImports(t, pkgDir)
 70→			for _, imp := range imports {
 71→				if !strings.HasPrefix(imp, repoPrefix) && imp != forbiddenCLIPackage {
 72→					continue // external or stdlib — allowed
 73→				}
 74→
 75→				// Check if it's the top-level cli package itself
 76→				if imp == forbiddenCLIPackage {
 77→					t.Errorf("forbidden import %q — agent packages must not import the top-level cli package directly", imp)
 78→					continue
 79→				}
 80→
 81→				// Check forbidden suffixes
 82→				rel := strings.TrimPrefix(imp, repoPrefix)
 83→				for _, forbidden := range forbiddenSuffixes {
 84→					if rel == forbidden || strings.HasPrefix(rel, forbidden+"/") {
 85→						t.Errorf("forbidden import %q — agent packages must not import %s internals", imp, forbidden)
 86→					}
 87→				}
 88→
 89→				// Check it's in the allowed list
 90→				allowed := false
 91→				for _, prefix := range allowedPrefixes {
 92→					if imp == prefix || strings.HasPrefix(imp, prefix+"/") {
 93→						allowed = true
 94→						break
 95→					}
 96→				}
 97→				if !allowed {
 98→					t.Errorf("unexpected internal import %q — if this is intentional, add it to allowedPrefixes in architecture_test.go", imp)
 99→				}
100→			}
101→		})
102→	}
103→}
