117→// discoverAgentPackages finds all subdirectories of the agent dir that contain
118→// Go files, excluding "types" and "testutil" (those are contract/shared packages).
119→func discoverAgentPackages(t *testing.T, agentDir string) []string {
120→	t.Helper()
121→
122→	skipDirs := map[string]bool{
123→		"types":    true, // contract types, not an agent implementation
124→		"testutil": true, // shared test utilities
125→	}
126→
127→	entries, err := os.ReadDir(agentDir)
128→	if err != nil {
129→		t.Fatalf("ReadDir(%s): %v", agentDir, err)
130→	}
131→
132→	var pkgs []string
133→	for _, e := range entries {
134→		if !e.IsDir() || skipDirs[e.Name()] {
135→			continue
136→		}
137→		dir := filepath.Join(agentDir, e.Name())
138→		// Only include if it has Go files
139→		goFiles, err := filepath.Glob(filepath.Join(dir, "*.go"))
140→		if err != nil {
141→			t.Fatalf("filepath.Glob(%s): %v", dir, err)
142→		}
143→		if len(goFiles) > 0 {
144→			pkgs = append(pkgs, dir)
145→		}
146→	}
147→	return pkgs
148→}
