150→// extractImports parses all Go files in a directory and returns unique import paths.
151→// Includes both production and test files — test-only imports should also respect boundaries.
152→func extractImports(t *testing.T, dir string) []string {
153→	t.Helper()
154→
155→	fset := token.NewFileSet()
156→	//nolint:staticcheck // ParseDir is deprecated in favor of go/packages, but we intentionally
157→	// scan all files regardless of build tags to catch forbidden imports in test files too.
158→	pkgs, err := parser.ParseDir(fset, dir, nil, parser.ImportsOnly)
159→	if err != nil {
160→		t.Fatalf("parser.ParseDir(%s): %v", dir, err)
161→	}
162→
163→	seen := make(map[string]bool)
164→	for _, pkg := range pkgs {
165→		for _, file := range pkg.Files {
166→			for _, imp := range file.Imports {
167→				path := strings.Trim(imp.Path.Value, `"`)
168→				seen[path] = true
169→			}
170→		}
171→	}
172→
173→	imports := make([]string, 0, len(seen))
174→	for imp := range seen {
175→		imports = append(imports, imp)
176→	}
177→	return imports
178→}
