180→// TestAgentPackages_SelfRegister verifies that each agent package has an init()
181→// function that calls agent.Register(). This ensures agents are properly
182→// discoverable via the registry.
183→func TestAgentPackages_SelfRegister(t *testing.T) {
184→	t.Parallel()
185→
186→	agentDir := findAgentDir(t)
187→	agentPkgs := discoverAgentPackages(t, agentDir)
188→
189→	for _, pkgDir := range agentPkgs {
190→		pkgName := filepath.Base(pkgDir)
191→		t.Run(pkgName, func(t *testing.T) {
192→			t.Parallel()
193→			if !hasInitWithRegister(t, pkgDir) {
194→				t.Errorf("agent package %q has no init() function calling Register() — agents must self-register", pkgName)
195→			}
196→		})
197→	}
198→}
