200→// hasInitWithRegister checks if any Go file in the directory has an init()
201→// function that contains a call to Register.
202→func hasInitWithRegister(t *testing.T, dir string) bool {
203→	t.Helper()
204→
205→	fset := token.NewFileSet()
206→	//nolint:staticcheck // See extractImports for rationale.
207→	pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool {
208→		return !strings.HasSuffix(fi.Name(), "_test.go")
209→	}, 0)
210→	if err != nil {
211→		t.Fatalf("parser.ParseDir(%s): %v", dir, err)
212→	}
213→
214→	for _, pkg := range pkgs {
215→		for _, file := range pkg.Files {
216→			for _, decl := range file.Decls {
217→				fn, ok := decl.(*ast.FuncDecl)
218→				if !ok || fn.Name.Name != "init" || fn.Recv != nil {
219→					continue
220→				}
221→				// Walk the init body looking for a call to Register or agent.Register
222→				found := false
223→				ast.Inspect(fn.Body, func(n ast.Node) bool {
224→					call, ok := n.(*ast.CallExpr)
225→					if !ok {
226→						return true
227→					}
228→					switch fun := call.Fun.(type) {
229→					case *ast.Ident:
230→						if fun.Name == "Register" {
231→							found = true
232→						}
233→					case *ast.SelectorExpr:
234→						if fun.Sel.Name == "Register" {
235→							found = true
236→						}
237→					}
238→					return !found
239→				})
240→				if found {
241→					return true
242→				}
243→			}
244→		}
245→	}
246→	return false
247→}
