// Go test runner sets cwd to the package directory, so os.Getwd() gives us
// the agent dir directly.
func findAgentDir(t *testing.T) string {
	t.Helper()
	wd, err := os.Getwd()
	if err != nil {
		t.Fatalf("os.Getwd: %v", err)
